"use client";
import { useState } from "react";

export default function CodeLitePage() {
  const [code, setCode] = useState("");
  const [result, setResult] = useState("");
  const [mode, setMode] = useState("normal");
  const [language, setLanguage] = useState("english");
  const [loading, setLoading] = useState(false);
  const [tokens, setTokens] = useState(0);
  const [cost, setCost] = useState(0);
  const [detectedLanguage, setDetectedLanguage] = useState("");

  const handleExplain = async () => {
    if (!code) return;

    setLoading(true);
    setResult("");

    const res = await fetch("/api/explain", {
      method: "POST",
      body: JSON.stringify({ code, mode, language }),
    });

    const data = await res.json();

    setResult(data.text);
    setTokens(data.tokens);
    setCost(data.cost);
    setDetectedLanguage(data.detectedLanguage);

    setLoading(false);
  };

  const efficiency =
    tokens && code.length ? (tokens / code.length).toFixed(2) : 0;

  return (
    <main style={{ padding: "40px", maxWidth: "800px", margin: "0 auto" }}>
      <h1>CodeLite ⚡</h1>

      <textarea
        placeholder="Paste your code..."
        value={code}
        onChange={(e) => setCode(e.target.value)}
        rows={10}
        style={{
          width: "100%",
          background: "#020617",
          color: "#e2e8f0",
          border: "1px solid #334155",
          borderRadius: "8px",
          padding: "12px",
          fontFamily: "monospace",
          marginBottom: "15px",
        }}
      />

      <div style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
        
        <label>
          <input
            type="checkbox"
            onChange={(e) =>
              setMode(e.target.checked ? "low" : "normal")
            }
          />
          Low Cost ⚡
        </label>

        <select
          value={language}
          onChange={(e) => setLanguage(e.target.value)}
          style={{ padding: "5px", borderRadius: "6px" }}
        >
          <option value="english">🇬🇧 English</option>
          <option value="spanish">🇪🇸 Español</option>
        </select>

        <button
          onClick={handleExplain}
          disabled={loading}
          style={{
            padding: "8px 14px",
            borderRadius: "6px",
            border: "none",
            background: loading ? "#334155" : "#22c55e",
            color: "black",
            fontWeight: "bold",
            cursor: "pointer",
          }}
        >
          {loading ? "Thinking..." : "Explain ⚡"}
        </button>
      </div>

      <div
        style={{
          marginTop: "20px",
          background: "#020617",
          border: "1px solid #334155",
          borderRadius: "8px",
          padding: "12px",
          minHeight: "80px",
          fontFamily: "monospace",
          color: "#38bdf8",
        }}
      >
        {loading && "Thinking..."}
        {!loading && result}
      </div>

      <div style={{ marginTop: "10px", fontSize: "12px", opacity: 0.8 }}>
        <p>🧠 Language: {detectedLanguage}</p>
        <p>🧮 Tokens: {tokens}</p>
        <p>💸 Cost: ${cost.toFixed(6)}</p>
        <p>⚡ Efficiency: {efficiency} tokens/char</p>

        {mode === "low" && (
          <p style={{ color: "#22c55e" }}>
            ⚡ Low Cost Mode Active
          </p>
        )}
      </div>
    </main>
  );
}